package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import org.junit.Test;import static org.junit.Assert.*;
public class AngleSumRelationsTest {
 @Test public void independentPublicAnglesDriveEachBlankAndNeverTransfer(){Generator g=new Generator(new Random(171));for(String id:List.of("el_triangle_angle_sum","el_quadrilateral_angle_sum"))for(int i=0;i<500;i++){
  Question q=g.create(Catalog.get(id));List<Integer> values=new ArrayList<>();Matcher m=Pattern.compile("(\\d+)도").matcher(q.prompt);while(m.find())values.add(Integer.parseInt(m.group(1)));int total=id.equals("el_triangle_angle_sum")?180:360,sum=values.stream().mapToInt(Integer::intValue).sum();assertEquals(total==180?2:3,values.size());values.add(sum);values.add(total-sum);assertTrue(new Checker().check(q,List.of(),List.of(""+(total-sum))).correct());Arrays.fill(q.answers,"999999");HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(values.size(),p.size());HelpPlan.Draft d=p.restore(null,q.id);for(int k=0;k<values.size();k++){assertTrue(p.step(k).accepts(values.get(k).toString()));assertFalse(p.step(k).accepts(""+(values.get(k)+1)));assertFalse(p.step(k).before.replace("180°","").replace("360°","").matches("(?s).*\\d.*"));d.entries.set(k,values.get(k).toString());d.stage++;d.entries.add("");}assertEquals(""+(total-sum),p.enteredAnswer(d));
 }}
 @Test public void legacyIntermediateDraftIsClearedAndNewAngleEntrySurvives(){Question q=new Question("el_triangle_angle_sum","40도, 75도","180-40-75","65");q.studyGuide=new StudyGuide().step("old","40 + 75 = ","°","115");HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("115",""));HelpPlan p=HelpPlan.forQuestion(q);p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"40");d.stage=1;d.entries.add("");HelpPlan.Draft restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("40",restored.entries.get(0));assertEquals("angle-sum-relations-v1",restored.teachingVersion);}
}
